import { supabase } from "../supabaseClient";

export async function listFeeStructures() {
  const { data, error } = await supabase
    .from("fee_structure")
    .select("id, class_id, academic_year, fee_type, amount, due_date, classes ( name, section )")
    .order("due_date");
  if (error) throw error;
  return data;
}

export async function addFeeStructure({ classId, academicYear, feeType, amount, dueDate }) {
  const { error } = await supabase.from("fee_structure").insert({
    class_id: classId,
    academic_year: academicYear,
    fee_type: feeType,
    amount,
    due_date: dueDate || null,
  });
  if (error) throw error;
}

export async function deleteFeeStructure(id) {
  const { error } = await supabase.from("fee_structure").delete().eq("id", id);
  if (error) throw error;
}

export async function listStudentsForClass(classId) {
  const { data, error } = await supabase
    .from("students")
    .select("id, roll_no, profiles!students_id_fkey ( full_name )")
    .eq("class_id", classId)
    .order("roll_no");
  if (error) throw error;
  return data;
}

export async function getFeeBalance(studentId, feeStructureId, amount) {
  const { data, error } = await supabase
    .from("fee_payments")
    .select("amount_paid, status")
    .eq("student_id", studentId)
    .eq("fee_structure_id", feeStructureId);
  if (error) throw error;
  const paidTotal = (data || [])
    .filter((p) => p.status === "paid" || p.status === "partial")
    .reduce((sum, p) => sum + Number(p.amount_paid || 0), 0);
  const remaining = Math.max(0, Number(amount) - paidTotal);
  return { paidTotal, remaining };
}

export async function recordPayment({ studentId, feeStructureId, amountPaid, paymentDate, mode, receiptNo, recordedBy, feeAmount }) {
  // Status is derived from the running total, not typed in by the admin —
  // otherwise a partial payment could be mislabeled "paid" by mistake.
  const { paidTotal } = await getFeeBalance(studentId, feeStructureId, feeAmount);
  const newTotal = paidTotal + Number(amountPaid);
  let status = "due";
  if (newTotal >= Number(feeAmount)) status = "paid";
  else if (newTotal > 0) status = "partial";

  const { error } = await supabase.from("fee_payments").insert({
    student_id: studentId,
    fee_structure_id: feeStructureId,
    amount_paid: amountPaid,
    payment_date: paymentDate || null,
    mode,
    status,
    receipt_no: receiptNo || null,
    recorded_by: recordedBy,
  });
  if (error) throw error;
  return { newTotal, remaining: Math.max(0, Number(feeAmount) - newTotal), status };
}

export async function listPaymentsForFeeStructure(feeStructureId) {
  const { data, error } = await supabase
    .from("fee_payments")
    .select("id, amount_paid, payment_date, mode, status, receipt_no, students ( roll_no, profiles!students_id_fkey ( full_name ) )")
    .eq("fee_structure_id", feeStructureId)
    .order("payment_date", { ascending: false });
  if (error) throw error;
  return data;
}

export async function listMyFeeStatus(studentId, classId) {
  const { data: structures, error: structureError } = await supabase
    .from("fee_structure")
    .select("id, fee_type, amount, due_date")
    .eq("class_id", classId);
  if (structureError) throw structureError;

  const { data: payments, error: paymentsError } = await supabase
    .from("fee_payments")
    .select("id, fee_structure_id, amount_paid, payment_date, mode, receipt_no, status")
    .eq("student_id", studentId);
  if (paymentsError) throw paymentsError;

  return structures.map((s) => {
    const relevant = payments.filter((p) => p.fee_structure_id === s.id);
    // Only admin-confirmed payments count toward the balance — a
    // submitted-but-unverified claim shouldn't reduce what's shown as due.
    const confirmed = relevant.filter((p) => p.status === "paid" || p.status === "partial");
    const paidTotal = confirmed.reduce((sum, p) => sum + Number(p.amount_paid || 0), 0);
    const remaining = Math.max(0, Number(s.amount) - paidTotal);
    const pending = relevant.filter((p) => p.status === "pending_verification");
    let status = "due";
    if (paidTotal >= Number(s.amount)) status = "paid";
    else if (paidTotal > 0) status = "partial";
    return { ...s, paidTotal, remaining, status, payments: relevant, pending };
  });
}

export async function submitPaymentRequest({ studentId, feeStructureId, amountPaid, mode, note }) {
  const { error } = await supabase.from("fee_payments").insert({
    student_id: studentId,
    fee_structure_id: feeStructureId,
    amount_paid: amountPaid,
    payment_date: new Date().toISOString().slice(0, 10),
    mode,
    status: "pending_verification",
    receipt_no: note || null,
  });
  if (error) throw error;
}

export async function listPendingPaymentRequests() {
  const { data, error } = await supabase
    .from("fee_payments")
    .select(
      "id, student_id, fee_structure_id, amount_paid, payment_date, mode, receipt_no, fee_structure ( fee_type, amount ), students ( roll_no, profiles!students_id_fkey ( full_name ) )"
    )
    .eq("status", "pending_verification")
    .order("payment_date", { ascending: false });
  if (error) throw error;
  return data;
}

export async function verifyPaymentRequest(id, decision, { studentId, feeStructureId, amountPaid, feeAmount }) {
  if (decision === "reject") {
    const { error } = await supabase.from("fee_payments").update({ status: "rejected" }).eq("id", id);
    if (error) throw error;
    return;
  }
  // Approve: sum the OTHER already-confirmed payments for this fee item
  // (excluding this pending row itself, which still holds its original
  // amount in the table) so the new status reflects the true running total.
  const { data, error: fetchError } = await supabase
    .from("fee_payments")
    .select("id, amount_paid, status")
    .eq("student_id", studentId)
    .eq("fee_structure_id", feeStructureId);
  if (fetchError) throw fetchError;
  const otherConfirmedTotal = (data || [])
    .filter((p) => p.id !== id && (p.status === "paid" || p.status === "partial"))
    .reduce((sum, p) => sum + Number(p.amount_paid || 0), 0);
  const newTotal = otherConfirmedTotal + Number(amountPaid);
  const status = newTotal >= Number(feeAmount) ? "paid" : "partial";
  const { error } = await supabase.from("fee_payments").update({ status }).eq("id", id);
  if (error) throw error;
}
